CREATE TABLE IF NOT EXISTS p10_voice_assets (
 id CHAR(32) NOT NULL,file_name VARCHAR(64) NOT NULL,owner_id BIGINT NOT NULL,request_id VARCHAR(64) NOT NULL,request_hash CHAR(64) NOT NULL,owner_session_hash CHAR(64) NOT NULL,chat_type BIGINT NOT NULL,scope VARCHAR(160) NOT NULL,target_id BIGINT NOT NULL DEFAULT 0,state BIGINT NOT NULL,bytes LONGBLOB NOT NULL,sha CHAR(64) NOT NULL,byte_length BIGINT NOT NULL,duration_millis BIGINT NOT NULL,created_at BIGINT NOT NULL,expires_at BIGINT NOT NULL,source TEXT NOT NULL,meta_hash CHAR(64) NOT NULL,PRIMARY KEY(id),UNIQUE KEY p10_voice_filename(file_name),UNIQUE KEY p10_voice_upload(owner_id,request_id),KEY p10_voice_owner(owner_id),KEY p10_voice_scope(scope),KEY p10_voice_expiry(expires_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
